 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r31-v2','0.2.0','Lesson 6 step 4 of 6: Predict, then find','reading','guided_practice','Read LEARN FIRST and the worked example. Then complete each sentence with NO MORE THAN TWO WORDS from the passage. Copy the words exactly.','Predict the kind of word, find the same meaning in the passage, then reject the nearby word that looks right but is not.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "During heatwaves, ________ rises as air conditioners run for longer.", "accepted_answers": ["electricity consumption"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q2", "prompt": "In a green roof, moisture ________ from the leaves and takes heat with it.", "accepted_answers": ["evaporates"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q3", "prompt": "Contrary to what might be expected, a city is warmest compared with the countryside not when the sun is strongest but well after ________.", "accepted_answers": ["dusk"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q4", "prompt": "Rooms directly under a green roof warm up less quickly because the growing layer provides ________.", "accepted_answers": ["insulation"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q5", "prompt": "On a very tall building, a planted roof may leave temperatures at ________ largely unchanged.", "accepted_answers": ["pavement level"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q6", "prompt": "Some councils charge owners of planted roofs lower ________ because these roofs hold back rainwater.", "accepted_answers": ["stormwater fees"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "teacher_notes": "1 electricity consumption (paragraph B): \"Electricity consumption climbs in parallel as air conditioners run for longer\". Rises = climbs. Trap: ''waste heat'' is what the machines expel, not what rises.\n2 evaporates (paragraph C): \"moisture drawn up through the roots evaporates from the leaves\". The gap needs a verb. Trap: ''drawn up'' happens in the roots, before the heat leaves.\n3 dusk (paragraph A): \"not in the early afternoon, when sunlight is most intense, but several hours after dusk\". ''Contrary to what might be expected'' = counter-intuitively. Trap: ''early afternoon'' is the time ruled out by ''not ... but''.\n4 insulation (paragraph C): \"The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below\". Growing layer = substrate. Trap: evapotranspiration cools the roof surface, not the rooms.\n5 pavement level (paragraph D): \"doing almost nothing for the air at pavement level\". Leave largely unchanged = do almost nothing for. Trap: ''upper floors'' are the part the roof does cool.\n6 stormwater fees (paragraph E): \"subsidies or reduced stormwater fees\". Charge lower = reduced. The gap needs something you are charged. Traps: ''sewers'' and ''drainage outlets'' are not charges.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Locate specific detail: complete sentences that paraphrase the passage, copying words exactly and rejecting nearby distractors."}'::jsonb || jsonb_build_object('passage', to_jsonb('LEARN FIRST: predict the word, find it, reject the trap

Write NO MORE THAN TWO WORDS from the passage. Copy them exactly: the spelling must match.
1. PREDICT: what kind of word fits the gap (noun, plural noun, verb, adjective, time word)?
2. FIND: the sentence in the question uses different words. Find the same MEANING in the passage.
3. REJECT: check the nearby word that looks right but is not.

WORKED EXAMPLE
"On hot afternoons, planted roofs are much cooler than nearby ________ surfaces."
1. Predict: a word that describes a kind of surface (one word, before "surfaces").
2. Find: "nearby" = "adjacent" in paragraph C: "dramatically cooler on hot afternoons than adjacent bitumen surfaces".
3. Reject: "individual buildings" is in the same sentence but is not a surface.
Answer: bitumen

Look for contrast words too (not ... but, while, although, rather than). The wrong answer often sits on the other side of them.' || '

